"use strict";const e=require("./api.js");exports.fetchProfile=async function(){return e.request({path:"/auth/profile"})},exports.login=async function(t,n){const o=(r={username:t,password:n,grant_type:"password"},Object.entries(r).map(([e,t])=>`${encodeURIComponent(e)}=${encodeURIComponent(String(t))}`).join("&"));var r;const s=await e.request({path:"/auth/login",method:"POST",data:o,headers:{"Content-Type":"application/x-www-form-urlencoded"}});return(null==s?void 0:s.access_token)&&e.setToken(s.access_token),s},exports.register=async function(t){return e.request({path:"/auth/register",method:"POST",data:t})};
